using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Core.Asistente;

public sealed record SolicitudAuditoria(
    string IpOrigen,
    string CorrelationId,
    Rol? Rol,
    string? UsuarioId,
    string? Pregunta,
    ResultadoAuditoria Resultado,
    long DuracionMs);

public sealed class AuditorPeticiones
{
    public const int LongitudMaximaPregunta = 1000;
    public const string PreguntaNoEvaluada = "[NO_EVALUADA]";

    private readonly IAuditoria _auditoria;
    private readonly IReloj _reloj;
    private DirectorioAcademico? _personasConocidas;

    public AuditorPeticiones(IAuditoria auditoria, IReloj reloj)
    {
        _auditoria = auditoria;
        _reloj = reloj;
    }

    public DateTimeOffset AhoraUtc => _reloj.AhoraUtc;

    public static string SanearPregunta(Usuario usuario, string? pregunta, DirectorioAcademico directorio)
    {
        if (string.IsNullOrEmpty(pregunta))
        {
            return string.Empty;
        }

        return Limpiar(DetectorTerceros.EnmascararTerceros(usuario, pregunta, directorio));
    }

    public void RecordarPersonas(DirectorioAcademico directorio) => Volatile.Write(ref _personasConocidas, directorio);

    public string PreguntaSinIdentidad(string? pregunta)
    {
        var personas = Volatile.Read(ref _personasConocidas);
        return pregunta is null || personas is null
            ? PreguntaNoEvaluada
            : Limpiar(DetectorTerceros.EnmascararPersonas(pregunta, personas));
    }

    private static string Limpiar(string enmascarada)
    {
        var sinControl = new string([.. enmascarada.Select(caracter => char.IsControl(caracter) ? ' ' : caracter)]);
        return sinControl.Length > LongitudMaximaPregunta ? sinControl[..LongitudMaximaPregunta] : sinControl;
    }

    public void Registrar(EventoAuditoria evento) => _auditoria.Registrar(evento);

    public void RegistrarSinConsultas(SolicitudAuditoria solicitud)
    {
        _auditoria.Registrar(new EventoAuditoria(
            _reloj.AhoraUtc,
            solicitud.CorrelationId,
            solicitud.IpOrigen,
            solicitud.Rol,
            solicitud.UsuarioId,
            PreguntaSinIdentidad(solicitud.Pregunta),
            solicitud.Resultado,
            null,
            [],
            [],
            [],
            0,
            0m,
            solicitud.DuracionMs,
            false));
    }

    public void RegistrarMultiplesIdentidades(string ipOrigen, IReadOnlyList<string> usuarioIds) =>
        _auditoria.RegistrarMultiplesIdentidades(new EventoMultiplesIdentidades(_reloj.AhoraUtc, ipOrigen, usuarioIds));
}
namespace TutorFlow.Core.Asistente;

public sealed record ResultadoIdentidades(bool SuperacionNueva, IReadOnlyList<string> Ids);

public sealed class LimitadorIdentidades
{
    private const int UmbralDeLimpieza = 10_000;

    private readonly Lock _candado = new();
    private readonly Dictionary<string, VentanaDeIp> _porIp = [];
    private readonly IReloj _reloj;
    private readonly LimitesAsistente _limites;

    public LimitadorIdentidades(IReloj reloj, LimitesAsistente limites)
    {
        _reloj = reloj;
        _limites = limites;
    }

    private TimeSpan Ventana => TimeSpan.FromMinutes(_limites.VentanaIdentidadesMinutos);

    public ResultadoIdentidades Registrar(string ipOrigen, string usuarioId)
    {
        lock (_candado)
        {
            var ahora = _reloj.AhoraUtc;
            LimpiarSiHaceFalta(ahora);
            var ventana = ObtenerVigente(ipOrigen, ahora);
            return ventana.Contiene(usuarioId)
                ? Renovar(ventana, usuarioId, ahora)
                : Admitir(ventana, usuarioId, ahora);
        }
    }

    private static ResultadoIdentidades Renovar(VentanaDeIp ventana, string usuarioId, DateTimeOffset ahora)
    {
        ventana.Registrar(usuarioId, ahora);
        return new ResultadoIdentidades(false, ventana.Ids);
    }

    private ResultadoIdentidades Admitir(VentanaDeIp ventana, string usuarioId, DateTimeOffset ahora)
    {
        var superada = ventana.Entradas.Count >= _limites.MaximoIdentidadesPorIp;
        ventana.Registrar(usuarioId, ahora);
        return new ResultadoIdentidades(superada, ventana.Ids);
    }

    private VentanaDeIp ObtenerVigente(string ipOrigen, DateTimeOffset ahora)
    {
        if (!_porIp.TryGetValue(ipOrigen, out var ventana))
        {
            ventana = new VentanaDeIp();
            _porIp[ipOrigen] = ventana;
        }

        ventana.Purgar(ahora, Ventana);
        return ventana;
    }

    private void LimpiarSiHaceFalta(DateTimeOffset ahora)
    {
        if (_porIp.Count < UmbralDeLimpieza)
        {
            return;
        }

        foreach (var (ip, ventana) in _porIp.ToList())
        {
            ventana.Purgar(ahora, Ventana);
            if (ventana.EstaVacia)
            {
                _porIp.Remove(ip);
            }
        }
    }

    private sealed class VentanaDeIp
    {
        public List<(DateTimeOffset Momento, string Id)> Entradas { get; } = [];

        public bool EstaVacia => Entradas.Count == 0;

        public IReadOnlyList<string> Ids => [.. Entradas.Select(e => e.Id)];

        public bool Contiene(string usuarioId) => Entradas.Exists(e => e.Id == usuarioId);

        public void Registrar(string usuarioId, DateTimeOffset ahora)
        {
            Entradas.RemoveAll(e => e.Id == usuarioId);
            Entradas.Add((ahora, usuarioId));
        }

        public void Purgar(DateTimeOffset ahora, TimeSpan ventana) =>
            Entradas.RemoveAll(e => ahora - e.Momento >= ventana);
    }
}
